-- Template for the optional standalone test addon generated by Test-AssetAtlases.py.
-- Creates only its own unprotected comparison window. No saved variables.
local addon = ...
local path = "Interface\\AddOns\\" .. addon .. "\\"
local entries = {
-- GENERATED_ROWS
}
local window
local function ShowTest()
	if window then window:SetShown(not window:IsShown()); return end
	window = CreateFrame("Frame", nil, UIParent)
	window:SetSize(600, 840)
	window:SetPoint("CENTER")
	window:SetFrameStrata("DIALOG")
	local background = window:CreateTexture(nil, "BACKGROUND")
	background:SetAllPoints()
	background:SetColorTexture(.07, .07, .07, .98)
	local function Text(text, x, y)
		local label = window:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		label:SetPoint("TOPLEFT", x, y)
		label:SetText(text)
	end
	Text("Atlas test: original (left) / cropped atlas (right)", 16, -16)
	local close = CreateFrame("Button", nil, window)
	close:SetSize(36, 26)
	close:SetPoint("TOPRIGHT", -6, -6)
	close:SetNormalFontObject("GameFontNormal")
	close:SetText("X")
	close:SetScript("OnClick", function() window:Hide() end)
	local scaleButton = CreateFrame("Button", nil, window)
	scaleButton:SetSize(200, 28)
	scaleButton:SetPoint("BOTTOMLEFT", 16, 8)
	scaleButton:SetNormalFontObject("GameFontNormal")
	scaleButton:SetText("Scale: 1.0 (click)")
	local scales, index = { 1, .75, 1.5 }, 1
	scaleButton:SetScript("OnClick", function(self)
		index = index % #scales + 1
		window:SetScale(scales[index])
		self:SetText("Scale: " .. scales[index] .. " (click)")
	end)
	local display = 117.5 -- Current proc-decoration canvas at a 64px button size.
	for i, entry in ipairs(entries) do
		local y = -42 - (i - 1) * 126
		Text(entry.name, 16, y)
		local original = window:CreateTexture(nil, "ARTWORK")
		original:SetTexture(path .. entry.name .. ".tga")
		original:SetSize(display, display)
		original:SetPoint("TOPLEFT", 250, y)
		local l, t, r, b = unpack(entry.crop)
		local atlas = window:CreateTexture(nil, "ARTWORK")
		atlas:SetTexture(path .. "proc-trimmed.tga")
		atlas:SetTexCoord(unpack(entry.uv))
		-- Restore the original virtual 256px canvas without stretching the crop.
		atlas:SetSize((r-l)/256*display, (b-t)/256*display)
		atlas:SetPoint("TOPLEFT", 410+l/256*display, y-t/256*display)
	end
end
SLASH_AZERITEUIATLASSMOKE1 = "/azatlastest"
SlashCmdList.AZERITEUIATLASSMOKE = ShowTest
